export type ParsedDrawJellybeanInstruction<
  TProgram extends string = typeof GUMBALL_GUARD_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Gumball Guard account. */
    gumballGuard: TAccountMetas[0];
    /**
     * Jellybean Machine program account.
     *
     */
    jellybeanMachineProgram: TAccountMetas[1];
    /** Jellybean machine account. */
    jellybeanMachine: TAccountMetas[2];
    jellybeanMachineAuthorityPda: TAccountMetas[3];
    /** Payer for the mint (SOL) fees. */
    payer: TAccountMetas[4];
    /** Minter account for validation and non-SOL fees. */
    buyer: TAccountMetas[5];
    unclaimedPrizes: TAccountMetas[6];
    /** Print fee account. Required if the jellybean machine has a print fee config. */
    printFeeAccount?: TAccountMetas[7] | undefined;
    /** SPL Token program. */
    splTokenProgram: TAccountMetas[8];
    /** System program. */
    systemProgram: TAccountMetas[9];
    /** Rent. */
    rent: TAccountMetas[10];
    /**
     * Instructions sysvar account.
     *
     */
    sysvarInstructions: TAccountMetas[11];
    /**
     * SlotHashes sysvar cluster data.
     *
     */
    recentSlothashes: TAccountMetas[12];
    jellybeanEventAuthority: TAccountMetas[13];
  };
  data: DrawJellybeanInstructionData;
};

export function parseDrawJellybeanInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedDrawJellybeanInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 14,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === GUMBALL_GUARD_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      gumballGuard: getNextAccount(),
      jellybeanMachineProgram: getNextAccount(),
      jellybeanMachine: getNextAccount(),
      jellybeanMachineAuthorityPda: getNextAccount(),
      payer: getNextAccount(),
      buyer: getNextAccount(),
      unclaimedPrizes: getNextAccount(),
      printFeeAccount: getNextOptionalAccount(),
      splTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      rent: getNextAccount(),
      sysvarInstructions: getNextAccount(),
      recentSlothashes: getNextAccount(),
      jellybeanEventAuthority: getNextAccount(),
    },
    data: getDrawJellybeanInstructionDataDecoder().decode(instruction.data),
  };
}
